head.script:
scwin.onpageload = function() {

};

	scwin.checkVal1 = function() {
		return (document.getElementById('wq_uuid_2') || document.getElementById('mf_wq_uuid_2')).getAttribute('aria-expanded') == 'false';
	}
	scwin.checkVal2 = function() {
		return (document.getElementById('wq_uuid_2') || document.getElementById('mf_wq_uuid_2')).getAttribute('aria-labelledby') === null;
	}			
	scwin.checkVal3 = function() {
		return (document.getElementById('wq_uuid_2_button') || document.getElementById('mf_wq_uuid_2_button')).getAttribute('aria-labelledby') === null;
	}		
	scwin.checkVal4 = function() {
		return (document.getElementById('wq_uuid_2_button') || document.getElementById('mf_wq_uuid_2_button')).getAttribute('aria-controls') === null;
	}
